discrete MHS
port:
    event input real Signal_Raw_Material_Arrived;
    event output real Condition_Load_Completed;
    event output real Condition_Transport_Completed;
state:
    initial state Idle
        when entry() then
            statehold(5);
        end;
        when receive(Signal_Raw_Material_Arrived) then
            transition(Loading);
        end;
    end;

    state Loading
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(Transporting);
            out
                send(Condition_Load_Completed, 1);
        end;
    end;

    state Transporting
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(Idle);
            out
                send(Condition_Transport_Completed, 1);
        end;
    end;
end;
end;

discrete CMS
port:
    event input real Signal_Raw_Material_Received;
    event output real Condition_Processing_Completed;
    event output real Condition_Sorting_Completed;
state:
    initial state Ready
        when entry() then
            statehold(5);
        end;
        when receive(Signal_Raw_Material_Received) then
            transition(Processing);
        end;
    end;

    state Processing
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(InspectionSorting);
            out
                send(Condition_Processing_Completed, 1);
        end;
    end;

    state InspectionSorting
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(Ready);
            out
                send(Condition_Sorting_Completed, 1);
        end;
    end;
end;
end;

discrete MAS
port:
    event input real Signal_Cells_Received;
    event output real Condition_Assembly_Completed;
    event output real Condition_Final_Check_Passed;
state:
    initial state WaitingForCells
        when entry() then
            statehold(5);
        end;
        when receive(Signal_Cells_Received) then
            transition(Assembly);
        end;
    end;

    state Assembly
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(FinalCheck);
            out
                send(Condition_Assembly_Completed, 1);
        end;
    end;

    state FinalCheck
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(WaitingForCells);
            out
                send(Condition_Final_Check_Passed, 1);
        end;
    end;
end;
end;

discrete QCS
port:
    event input real Condition_Abnormal_Detected;
    event output real Condition_Abnormality_Handled;
state:
    initial state Monitoring
        when entry() then
            statehold(5);
        end;
        when receive(Condition_Abnormal_Detected) then
            transition(HandlingAbnormality);
        end;
    end;

    state HandlingAbnormality
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(Monitoring);
            out
                send(Condition_Abnormality_Handled, 1);
            end;
        end;
    end;
end;

couple PVPanelProductionSystem
import architectureModels.MHS as MHS;
import architectureModels.CMS as CMS;
import architectureModels.MAS as MAS;
import architectureModels.QCS as QCS;
part:
    MHS mhs;
    CMS cms;
    MAS mas;
    QCS qcs;
connection:
    connect(mhs.Condition_Transport_Completed, cms.Signal_Raw_Material_Received);
    connect(cms.Condition_Sorting_Completed, mas.Signal_Cells_Received);
    connect(mas.Condition_Final_Check_Passed, qcs.Condition_Abnormal_Detected);
    connect(qcs.Condition_Abnormality_Handled, mhs.Signal_Raw_Material_Arrived);
end;
